def _holder_hint(self) -> str:
    """The pid recorded in the lock file, for the refusal message. Best-effort."""
    try:
        with open(self.lock_path, encoding="utf-8") as handle:
            return handle.read().strip() or "unrecorded"
    except OSError:
        return "unreadable"

